#!/usr/bin/env python3
"""Sorting visualizer: bubble sort with step-by-step output."""
def bubble_sort_visual(arr):
    a = arr[:]
    swaps = 0
    n = len(a)
    print("start:", a)
    for i in range(n):
        for j in range(n - 1 - i):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swaps += 1
                print("swap %d <-> %d:" % (j, j + 1), a)
    print("sorted:", a, "| swaps:", swaps)
    return a

if __name__ == "__main__":
    result = bubble_sort_visual([5, 2, 9, 1, 5, 6])
    assert result == [1, 2, 5, 5, 6, 9]
    print("OK: output is sorted")

#!/usr/bin/env python3
"""Markdown parser: converts a markdown subset to HTML."""
import re

def md_to_html(md):
    out = []
    for line in md.split("\n"):
        s = line.rstrip()
        if s.startswith("### "):
            out.append("<h3>%s</h3>" % s[4:]); continue
        if s.startswith("## "):
            out.append("<h2>%s</h2>" % s[3:]); continue
        if s.startswith("# "):
            out.append("<h1>%s</h1>" % s[2:]); continue
        if s.startswith("- "):
            out.append("<li>%s</li>" % s[2:]); continue
        if s.strip() == "":
            out.append(""); continue
        out.append("<p>%s</p>" % s)
    html = "\n".join(out)
    html = re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", html)
    html = re.sub(r"\*(.+?)\*", r"<i>\1</i>", html)
    html = re.sub(r"`(.+?)`", r"<code>\1</code>", html)
    html = re.sub(r"\[(.+?)\]\((.+?)\)", r'<a href="\2">\1</a>', html)
    html = html.replace("<li>", "<ul>\n<li>", 1)
    if "<li>" in html:
        html = html.replace("</li>\n<ul>", "</li>")
    return html

SAMPLE = "# Hello\n\nThis is **bold** and *italic* with `code`.\n\n- item one\n- item two\n\nA [link](https://example.com)."

if __name__ == "__main__":
    html = md_to_html(SAMPLE)
    print(html)
    assert "<h1>Hello</h1>" in html and "<b>bold</b>" in html and "<li>item one</li>" in html
    print("OK: markdown converted to HTML")

#!/usr/bin/env python3
"""Prime sieve: Sieve of Eratosthenes."""
def sieve(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return [i for i, p in enumerate(is_prime) if p]

if __name__ == "__main__":
    primes = sieve(100)
    print("primes up to 100:", primes)
    print("count:", len(primes))
    assert len(primes) == 25 and primes[:5] == [2, 3, 5, 7, 11]
    assert sieve(1000)[-1] == 997
    print("OK: 25 primes up to 100, largest prime under 1000 is 997")

