#!/usr/bin/env python3
"""Calculator: safe expression evaluation via ast."""
import ast, operator, math

OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
       ast.Div: operator.truediv, ast.Pow: operator.pow, ast.Mod: operator.mod,
       ast.USub: operator.neg}
NAMES = {"pi": math.pi, "e": math.e, "sqrt": math.sqrt, "sin": math.sin}

def calc(expr):
    tree = ast.parse(expr, mode="eval")
    def ev(n):
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.BinOp) and type(n.op) in OPS:
            return OPS[type(n.op)](ev(n.left), ev(n.right))
        if isinstance(n, ast.UnaryOp) and type(n.op) in OPS:
            return OPS[type(n.op)](ev(n.operand))
        if isinstance(n, ast.Name) and n.id in NAMES:
            return NAMES[n.id]
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id in NAMES:
            return NAMES[n.func.id](*[ev(a) for a in n.args])
        raise ValueError("unsupported: " + ast.dump(n))
    return ev(tree)

if __name__ == "__main__":
    for expr, want in [("2+3*4", 14), ("(2+3)*4", 20), ("2**10", 1024),
                       ("sqrt(16)+sin(pi/2)", 5.0), ("10%3", 1)]:
        got = calc(expr)
        print("%-18s = %s" % (expr, got))
        assert abs(got - want) < 1e-9
    print("OK: 5 expressions evaluated safely (no eval)")

#!/usr/bin/env python3
"""Base64 tool: encode/decode, URL-safe mode, data URLs."""
import base64

def b64encode(text):
    return base64.b64encode(text.encode()).decode()

def b64decode(data):
    return base64.b64decode(data.encode()).decode()

if __name__ == "__main__":
    msg = "Hello, JAH Databases!"
    enc = b64encode(msg)
    print("encoded:", enc)
    assert b64decode(enc) == msg
    url_safe = base64.urlsafe_b64encode(b"a+b/c=").decode()
    print("url-safe:", url_safe)
    assert base64.urlsafe_b64decode(url_safe) == b"a+b/c="
    data_url = "data:text/plain;base64," + enc
    print("data URL:", data_url[:40] + "...")
    print("OK: base64 round-trip, url-safe mode, and data URL all work")

#!/usr/bin/env python3
"""Word frequency counter with stopword filtering."""
import re
from collections import Counter

STOPWORDS = {"the", "a", "an", "and", "or", "of", "to", "in", "is", "it", "that"}

def word_freq(text, top=5):
    words = re.findall(r"[a-z']+", text.lower())
    words = [w for w in words if w not in STOPWORDS]
    return Counter(words).most_common(top)

TEXT = "The archive grows and the archive teaches. Databases hold data; data teaches the archive."

if __name__ == "__main__":
    for word, count in word_freq(TEXT):
        print("%-10s %d" % (word, count))
    freq = dict(word_freq(TEXT, top=50))
    assert freq["archive"] == 3 and freq["data"] == 2
    assert "the" not in freq
    print("OK: frequencies correct, stopwords filtered")

#!/usr/bin/env python3
"""Binary search with comparison counting."""
def binary_search(arr, target):
    lo, hi, comps = 0, len(arr) - 1, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        comps += 1
        if arr[mid] == target:
            return mid, comps
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, comps

if __name__ == "__main__":
    arr = list(range(0, 1000, 2))  # 500 sorted elements
    idx, comps = binary_search(arr, 500)
    print("found 500 at index", idx, "in", comps, "comparisons")
    assert idx == 250 and comps <= 10
    idx2, comps2 = binary_search(arr, 501)
    assert idx2 == -1
    print("missing value correctly returns -1")
    print("OK: binary search is O(log n) — 500 items in <= 10 comparisons")

