#!/usr/bin/env python3
"""URL parser: decompose a URL without network access."""
from urllib.parse import urlparse, parse_qs

def parse_url(url):
    p = urlparse(url)
    return {"scheme": p.scheme, "host": p.hostname, "port": p.port,
            "path": p.path, "query": parse_qs(p.query), "fragment": p.fragment}

if __name__ == "__main__":
    u = "https://example.com:8080/search?q=jahn+db&lang=en#results"
    parts = parse_url(u)
    for k, v in parts.items():
        print("%-8s: %s" % (k, v))
    assert parts["scheme"] == "https" and parts["host"] == "example.com"
    assert parts["port"] == 8080 and parts["query"] == {"q": ["jahn db"], "lang": ["en"]}
    assert parts["fragment"] == "results"
    print("OK: URL fully decomposed")

#!/usr/bin/env python3
"""Maze generator: recursive backtracker, ASCII output."""
import random

def gen_maze(w, h, seed=3):
    rng = random.Random(seed)
    maze = [[1] * (2 * w + 1) for _ in range(2 * h + 1)]
    stack = [(0, 0)]
    seen = {(0, 0)}
    maze[1][1] = 0
    while stack:
        cx, cy = stack[-1]
        nbs = []
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = cx + dx, cy + dy
            if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in seen:
                nbs.append((nx, ny, dx, dy))
        if nbs:
            nx, ny, dx, dy = rng.choice(nbs)
            maze[2 * cy + 1 + dy][2 * cx + 1 + dx] = 0
            maze[2 * ny + 1][2 * nx + 1] = 0
            seen.add((nx, ny))
            stack.append((nx, ny))
        else:
            stack.pop()
    return maze

if __name__ == "__main__":
    maze = gen_maze(10, 6)
    for row in maze:
        print("".join("#" if c else " " for c in row))
    open_cells = sum(1 for row in maze for c in row if c == 0)
    assert open_cells == 2 * 10 * 6 - 1, "perfect maze has exactly 2wh-1 open cells"
    print("OK: 10x6 perfect maze, %d open cells (spanning tree)" % open_cells)

#!/usr/bin/env python3
"""To-do list: add/complete/list with JSON persistence (scripted demo)."""
import json, os, tempfile

class Todo:
    def __init__(self, path):
        self.path = path
        self.items = []
        if os.path.exists(path):
            self.items = json.load(open(path))
    def add(self, task):
        self.items.append({"task": task, "done": False})
    def complete(self, i):
        self.items[i]["done"] = True
    def save(self):
        json.dump(self.items, open(self.path, "w"), indent=2)
    def show(self):
        for i, it in enumerate(self.items):
            print("[%s] %d. %s" % ("x" if it["done"] else " ", i, it["task"]))

if __name__ == "__main__":
    path = tempfile.mktemp(suffix=".json")
    t = Todo(path)
    t.add("Write database records"); t.add("Test every demo"); t.add("Ship the lane")
    t.complete(1)
    t.save()
    print("saved list:")
    t.show()
    t2 = Todo(path)  # reload from disk
    assert t2.items[1]["done"] and len(t2.items) == 3
    os.unlink(path)
    print("OK: add/complete/persist round-trip verified")

#!/usr/bin/env python3
"""Stopwatch: context manager + decorator for timing code."""
import time
from contextlib import contextmanager

@contextmanager
def stopwatch(label):
    t0 = time.perf_counter()
    yield
    print("%s: %.4f seconds" % (label, time.perf_counter() - t0))

def timed(fn):
    def wrap(*a, **k):
        t0 = time.perf_counter()
        r = fn(*a, **k)
        print("%s took %.4fs" % (fn.__name__, time.perf_counter() - t0))
        return r
    return wrap

@timed
def work(n):
    return sum(i * i for i in range(n))

if __name__ == "__main__":
    with stopwatch("list comprehension"):
        data = [i ** 2 for i in range(200000)]
    r = work(200000)
    assert r == sum(i * i for i in range(200000))
    print("OK: stopwatch and @timed decorator both work")
